'use client';
import React,{useEffect,useState,useCallback} from 'react';
import {LayoutDashboard,Users,MessageSquare,FileText,FileCheck2,ClipboardList,CalendarDays,Truck,UsersRound,Wallet,Receipt,Banknote,CreditCard,Landmark,ArrowLeftRight,Settings,Bell,Search,Plus,ArrowUpRight,ArrowLeft,Check,CheckCircle2,Clock,ChevronRight,ChevronDown,LogOut,Menu,X,Printer,Download,Upload,Camera,MapPin,House,UserRound,RefreshCw,ShieldCheck,AlertCircle,Send,Loader2,MoreHorizontal,FolderOpen,Mail} from 'lucide-react';
import {demoSnapshot} from '@/lib/demo';
